using Clock=std::chrono::steady_clock;
void reap(tom::HelperProcess& helper){helper.terminate();const auto deadline=Clock::now()+std::chrono::milliseconds(500);while(helper.running()&&Clock::now()<deadline){try{helper.poll();}catch(...){break;}std::this_thread::sleep_for(std::chrono::milliseconds(1));}product::require(!helper.running(),"tom-illustration-helper-reap");}
void boundCache(const std::filesystem::path& directory,unsigned maximum,const std::filesystem::path& keep){underlay::privateDirectory(directory);std::vector<std::pair<std::filesystem::file_time_type,std::filesystem::path>> files;for(const auto& e:std::filesystem::directory_iterator(directory)){product::require(files.size()<128,"tom-illustration-cache-capacity");struct stat st{};auto p=e.path();product::require(!lstat(p.c_str(),&st)&&S_ISREG(st.st_mode)&&st.st_uid==getuid()&&st.st_nlink==1&&(st.st_mode&0777)==0600&&!QUuid(QString::fromStdString(p.stem().string())).isNull(),"tom-illustration-cache-identity");files.push_back({e.last_write_time(),p});}std::sort(files.begin(),files.end());unsigned count=unsigned(files.size());for(const auto& [time,path]:files){(void)time;if(count<=maximum)break;if(path!=keep){product::require(!unlink(path.c_str()),"tom-illustration-cache-retire");--count;}}}
