  auto invoke=[&](const QString& action){product::require(helper.start(action,id,id),"tom-illustration-helper-start");while(helper.running()){product::require(!canceled.load()&&Clock::now()<deadline,"tom-illustration-canceled-or-timeout");if(auto result=helper.poll()){if(!(*result)["ok"].toBool()&&(*result)["retry_after_ms"].toInt()>0){const auto wait=Clock::now()+std::chrono::milliseconds((*result)["retry_after_ms"].toInt());while(Clock::now()<wait){product::require(!canceled.load()&&Clock::now()<deadline,"tom-illustration-canceled-or-timeout");std::this_thread::sleep_for(std::chrono::milliseconds(10));}product::require(helper.start("ink-poll",id,id),"tom-illustration-helper-retry");continue;}product::require((*result)["ok"].toBool(),"tom-illustration-provider-failed");return *result;}std::this_thread::sleep_for(std::chrono::milliseconds(2));}throw std::runtime_error("tom-illustration-result-missing");};
  try{product::require(!canceled.load(),"tom-illustration-canceled");unsigned pending=0;for(const auto& e:std::filesystem::directory_iterator(cancellations)){product::require(++pending<=64,"tom-illustration-cancel-capacity");auto oldId=QString::fromStdString(e.path().stem().string());product::require(!QUuid(oldId).isNull(),"tom-illustration-cancel-identity");auto queued=underlay::readBounded(e.path(),262144);auto saved=QJsonDocument::fromJson(queued).object();product::require(saved["request_id"]==oldId,"tom-illustration-cancel-binding");auto input=requests/(oldId.toStdString()+".json");if(!std::filesystem::exists(input))underlay::atomicFile(input,queued);product::require(helper.start("ink-cancel",oldId,oldId),"tom-illustration-cancel-start");const auto until=Clock::now()+std::chrono::milliseconds(1500);bool confirmed=false;while(helper.running()&&Clock::now()<until&&!canceled.load()){if(auto result=helper.poll()){confirmed=(*result)["ok"].toBool();break;}std::this_thread::sleep_for(std::chrono::milliseconds(2));}reap(helper);if(confirmed)product::require(!unlink(e.path().c_str()),"tom-illustration-cancel-retire");break;}product::require(!canceled.load(),"tom-illustration-canceled");created=true;auto result=invoke("ink-create");while(result["status"]!="completed"){product::require(result["status"]=="queued"||result["status"]=="generating"||result["status"]=="downloading","tom-illustration-interrupted");for(int n=0;n<250;++n){product::require(!canceled.load()&&Clock::now()<deadline,"tom-illustration-canceled-or-timeout");std::this_thread::sleep_for(std::chrono::milliseconds(2));}result=invoke("ink-poll");}auto raster=underlay::readBounded(image,6*1024*1024);product::require(QString::fromLatin1(underlay::digest(raster).toHex())==result["image_sha256"].toString(),"tom-illustration-image-binding");boundCache(images,8,image);return raster;
  }catch(...){auto error=std::current_exception();reap(helper);if(created){underlay::atomicFile(cancel,bytes);bool confirmed=false;try{helper.start("ink-cancel",id,id);const auto until=Clock::now()+std::chrono::milliseconds(1500);while(helper.running()&&Clock::now()<until){if(auto result=helper.poll()){confirmed=(*result)["ok"].toBool();break;}std::this_thread::sleep_for(std::chrono::milliseconds(2));}reap(helper);}catch(...){reap(helper);}if(confirmed)product::require(!unlink(cancel.c_str()),"tom-illustration-cancel-retire");}std::rethrow_exception(error);}
